dunning.mjs.text:
// Decline-code-aware failed-payment recovery planning. Pure: no I/O, no clock,
// no Node-only imports, so the same file runs in the browser simulator and in
// the self-hosted server. Times are UTC.

// Stripe decline_code -> what recovery should do about it.
//   hard   the issuer says do not retry (lost, stolen, restricted): ask for another card, never retry
//   update the card itself is unusable (expired, wrong number): retrying is futile until it is replaced
//   funds  insufficient funds / velocity limits: retrying can work, timing matters
//   auth   the bank wants the customer to authenticate (SCA/3DS): only the customer can fix it
//   soft   generic / temporary issuer declines: spaced retries
const CLASS_OF = {
  stolen_card: "hard", lost_card: "hard", pickup_card: "hard", fraudulent: "hard",
  restricted_card: "hard", invalid_account: "hard", new_account_information_failed: "hard",
  expired_card: "update", incorrect_number: "update", invalid_number: "update",
  invalid_expiry_month: "update", invalid_expiry_year: "update", invalid_cvc: "update",
  incorrect_cvc: "update", incorrect_zip: "update", card_not_supported: "update",
  currency_not_supported: "update",
  insufficient_funds: "funds", withdrawal_count_limit_exceeded: "funds", card_velocity_exceeded: "funds",
  authentication_required: "auth", authentication_not_handled: "auth",
};

export const DECLINE_CODES = Object.keys(CLASS_OF).concat([
  "generic_decline", "do_not_honor", "try_again_later", "issuer_not_available",
  "processing_error", "reenter_transaction", "call_issuer", "transaction_not_allowed",
]);

export function classifyDecline(code) {
  const c = String(code || "").trim().toLowerCase();
  return CLASS_OF[c] || "soft";
}

export const RETRYABLE = new Set(["funds", "soft"]);

export const DEFAULT_POLICY = {
  graceDays: 14,
  emailDays: [0, 3, 7, 11],
  softRetryDays: [1, 3, 6, 10],
  fundsRetryDays: [2, 5, 9, 13],
  paydayAware: true,
  retryHourUtc: 10,
  emailHourUtc: 15,
  maxRetries: 4,
};

export function mergePolicy(over = {}) {
  const p = { ...DEFAULT_POLICY, ...over };
  for (const k of ["emailDays", "softRetryDays", "fundsRetryDays"]) {
    if (!Array.isArray(p[k]) || p[k].some((n) => !Number.isFinite(n) || n < 0)) throw new Error(`policy.${k} must be an array of non-negative numbers`);
  }
  for (const k of ["graceDays", "maxRetries", "retryHourUtc", "emailHourUtc"]) {
    if (!Number.isFinite(p[k]) || p[k] < 0) throw new Error(`policy.${k} must be a non-negative number`);
  }
  if (p.retryHourUtc > 23 || p.emailHourUtc > 23) throw new Error("policy hours must be 0-23");
  return p;
}

const DAY = 86400000;
const startOfDay = (ms) => ms - (((ms % DAY) + DAY) % DAY);

// Cards issued to people on a wage tend to clear when the money lands. This is
// a heuristic, not a measured effect: nudge a "funds" retry to the first of
// 1st/2nd/15th/16th of the month or a Friday that falls within two days after
// its nominal day. Turn off with paydayAware: false.
export function snapToPayday(dayStartMs) {
  for (let i = 0; i <= 2; i++) {
    const d = new Date(dayStartMs + i * DAY);
    const dom = d.getUTCDate();
    if ([1, 2, 15, 16].includes(dom) || d.getUTCDay() === 5) return dayStartMs + i * DAY;
  }
  return dayStartMs;
}

export function emailTemplateFor(cls, index, total) {
  const stage = index === 0 ? "first" : index === total - 1 && total > 1 ? "final" : "reminder";
  return `${cls}-${stage}`;
}

// The ordered list of things recovery will do after a failed payment at time
// t0 (ms). Retries only exist for retryable classes. Every step id is stable,
// so a later failure of the same invoice can drop only what no longer applies.
export function planRecovery({ declineCode, t0, policy = {} }) {
  const p = mergePolicy(policy);
  const cls = classifyDecline(declineCode);
  const day0 = startOfDay(t0);
  const steps = [];
  const emailDays = [...new Set(p.emailDays)].sort((a, b) => a - b).filter((d) => d <= p.graceDays);
  emailDays.forEach((d, i) => {
    const at = d === 0 ? t0 : day0 + d * DAY + p.emailHourUtc * 3600000;
    steps.push({ id: `email${i}`, kind: "email", template: emailTemplateFor(cls, i, emailDays.length), at, status: "pending" });
  });
  if (RETRYABLE.has(cls)) {
    const days = (cls === "funds" ? p.fundsRetryDays : p.softRetryDays).slice(0, p.maxRetries);
    let prev = day0;
    days.forEach((d, i) => {
      let dayMs = day0 + d * DAY;
      if (cls === "funds" && p.paydayAware) dayMs = snapToPayday(dayMs);
      if (dayMs <= prev) dayMs = prev + DAY;
      prev = dayMs;
      if (dayMs - day0 > p.graceDays * DAY) return;
      steps.push({ id: `retry${i}`, kind: "retry", at: dayMs + p.retryHourUtc * 3600000, status: "pending" });
    });
  }
  steps.push({ id: "expire", kind: "expire", at: day0 + p.graceDays * DAY + p.emailHourUtc * 3600000, status: "pending" });
  steps.sort((a, b) => a.at - b.at || (a.kind === "email" ? -1 : 1));
  return { class: cls, steps };
}

// Re-plan after another failure of the same invoice. Done steps stay done. If
// the class changed (say a retry came back "lost_card"), pending steps are
// replaced by a plan for the new class, keeping the emails already sent so the
// customer is not sent "first notice" twice.
export function replan(existing, { declineCode, now, policy = {} }) {
  const next = planRecovery({ declineCode, t0: existing.t0, policy });
  if (next.class === existing.class) return { class: existing.class, steps: existing.steps };
  const kept = existing.steps.filter((s) => s.status !== "pending");
  const sentEmails = kept.filter((s) => s.kind === "email").length;
  const fresh = next.steps.filter((s) => s.id !== "expire" ? !(s.kind === "email" && Number(s.id.slice(5)) < sentEmails) : true)
    .filter((s) => s.at >= now - 1000 || s.id === "expire");
  const ids = new Set(kept.map((s) => s.id));
  return { class: next.class, steps: [...kept, ...fresh.filter((s) => !ids.has(s.id))].sort((a, b) => a.at - b.at) };
}

export function formatMoney(amountMinor, currency) {
  const cur = String(currency || "usd").toUpperCase();
  const zero = ["JPY", "KRW", "VND", "CLP", "ISK", "UGX", "XAF", "XOF", "PYG", "RWF"].includes(cur);
  const n = zero ? amountMinor : amountMinor / 100;
  try {
    return new Intl.NumberFormat("en", { style: "currency", currency: cur, maximumFractionDigits: zero ? 0 : 2 }).format(n);
  } catch {
    return `${n.toFixed(zero ? 0 : 2)} ${cur}`;
  }
}

engine.mjs.text:
// The recovery state machine. Holds a `state` object ({cases, seen}) that the
// server persists as JSON. Effects (Stripe, email, alerts) are injected so the
// whole thing is testable without a network.
import { planRecovery, replan, classifyDecline, formatMoney, mergePolicy } from "./dunning.mjs";
import { renderEmail } from "./templates.mjs";
import { findExpiring } from "./expiry.mjs";
import { assignArm, experiment } from "./holdout.mjs";

export function newState() { return { cases: {}, seen: [], stats: { recoveredMinor: {}, recovered: 0, lost: 0, emails: 0, retries: 0 } }; }

const MAX_SEEN = 500;
const MAX_ATTEMPTS = 3; // per step, then it is marked failed and the owner is told

function closeCase(state, c, outcome, now) {
  if (c.status !== "open") return;
  c.status = outcome; c.closedAt = now;
  for (const s of c.steps) if (s.status === "pending") s.status = "skipped";
  if (outcome === "recovered") {
    state.stats.recovered += 1;
    state.stats.recoveredMinor[c.currency] = (state.stats.recoveredMinor[c.currency] || 0) + c.amountMinor;
  } else if (outcome === "lost") state.stats.lost += 1;
}

// Feed one verified Stripe event in. `declineCode` is resolved by the caller
// (it needs an API call) and only used for payment_failed.
export function applyEvent(state, event, { now, policy, declineCode, holdoutPct = 0 }) {
  if (state.seen.includes(event.id)) return { ignored: "duplicate" };
  state.seen.push(event.id);
  if (state.seen.length > MAX_SEEN) state.seen.splice(0, state.seen.length - MAX_SEEN);
  const obj = event.data?.object || {};
  switch (event.type) {
    case "invoice.payment_failed": {
      if (!obj.id) return { ignored: "no invoice id" };
      if (obj.paid || obj.status === "paid") return { ignored: "already paid" };
      const existing = state.cases[obj.id];
      if (existing && existing.status === "open") {
        existing.attempts = obj.attempt_count ?? existing.attempts + 1;
        existing.lastDecline = declineCode || existing.lastDecline;
        if (existing.arm === "holdout") return { updated: obj.id, class: existing.class, arm: "holdout" };
        const next = replan(existing, { declineCode: existing.lastDecline, now, policy });
        existing.class = next.class; existing.steps = next.steps;
        return { updated: obj.id, class: existing.class };
      }
      const plan = planRecovery({ declineCode, t0: now, policy });
      const arm = assignArm(obj.customer || obj.id, holdoutPct);
      // Holdout: record the failure, take no action, close it on the same clock.
      if (arm === "holdout") plan.steps = plan.steps.filter((s) => s.kind === "expire");
      state.cases[obj.id] = {
        ...(holdoutPct ? { arm } : {}),
        invoiceId: obj.id, customer: obj.customer, subscription: obj.subscription || obj.parent?.subscription_details?.subscription || null,
        email: obj.customer_email || null, name: obj.customer_name || null,
        amountMinor: obj.amount_remaining ?? obj.amount_due ?? 0, currency: obj.currency || "usd",
        hostedUrl: obj.hosted_invoice_url || null, t0: now, attempts: obj.attempt_count ?? 1,
        lastDecline: declineCode || null, class: plan.class, steps: plan.steps, status: "open", log: [],
      };
      return { opened: obj.id, class: plan.class };
    }
    case "invoice.paid": case "invoice.payment_succeeded": {
      const c = state.cases[obj.id];
      if (c) closeCase(state, c, "recovered", now);
      return c ? { closed: obj.id, outcome: "recovered" } : { ignored: "no case" };
    }
    case "invoice.voided": case "invoice.marked_uncollectible": {
      const c = state.cases[obj.id];
      if (c) closeCase(state, c, "voided", now);
      return c ? { closed: obj.id, outcome: "voided" } : { ignored: "no case" };
    }
    case "customer.subscription.deleted": {
      let n = 0;
      for (const c of Object.values(state.cases)) if (c.status === "open" && c.subscription === obj.id) { closeCase(state, c, "voided", now); n++; }
      return { closed: n };
    }
    case "payment_method.attached": case "customer.updated": {
      // Customer put a new card on file: try the open invoices now, once.
      const cust = obj.customer || (event.type === "customer.updated" ? obj.id : null);
      let n = 0;
      for (const c of Object.values(state.cases)) {
        if (c.status === "open" && c.arm !== "holdout" && c.customer === cust && !c.steps.some((s) => s.id.startsWith("card-updated") && s.status === "pending")) {
          c.steps.push({ id: `card-updated-${now}`, kind: "retry", at: now, status: "pending", reason: "card updated" }); n++;
        }
      }
      return { queued: n };
    }
    default:
      return { ignored: event.type };
  }
}

export function dueSteps(state, now) {
  const out = [];
  for (const c of Object.values(state.cases)) {
    if (c.status !== "open") continue;
    for (const s of c.steps) if (s.status === "pending" && s.at <= now) out.push({ c, s });
  }
  return out.sort((a, b) => a.s.at - b.s.at);
}

function emailVars(c, deps) {
  return {
    name: c.name || "there", amount: formatMoney(c.amountMinor, c.currency), company: deps.company || "our team",
    address: deps.address || "", update_url: deps.updateUrl(c), deadline: new Date(c.t0 + (deps.policy.graceDays) * 86400000).toISOString().slice(0, 10),
  };
}

// Run everything due. deps: {stripe, sendEmail, alert, updateUrl, company, address, policy, dryRun, cancelOnExpire}
export async function tick(state, now, deps) {
  const policy = mergePolicy(deps.policy);
  const done = [];
  for (const { c, s } of dueSteps(state, now)) {
    if (c.status !== "open") continue;
    const note = (msg) => { c.log.push({ at: now, step: s.id, msg }); done.push(`${c.invoiceId} ${s.id}: ${msg}`); };
    try {
      if (s.kind === "email") {
        if (!c.email) { s.status = "skipped"; note("no customer email on invoice"); continue; }
        const mail = renderEmail(s.template, emailVars(c, { ...deps, policy }));
        if (!deps.dryRun) await deps.sendEmail({ to: c.email, ...mail });
        s.status = "done"; state.stats.emails += 1; note(deps.dryRun ? `dry run: would email ${s.template}` : `emailed ${s.template}`);
      } else if (s.kind === "retry") {
        if (deps.dryRun) { s.status = "done"; note("dry run: would retry payment"); continue; }
        const inv = await deps.stripe.getInvoice(c.invoiceId);
        if (inv.status !== "open") { closeCase(state, c, inv.status === "paid" ? "recovered" : "voided", now); note(`invoice is ${inv.status}`); continue; }
        state.stats.retries += 1;
        try {
          await deps.stripe.payInvoice(c.invoiceId, `dd-${c.invoiceId}-${s.id}`);
          s.status = "done"; closeCase(state, c, "recovered", now); note("retry succeeded");
        } catch (e) {
          if (e.status && e.status !== 402 && e.status < 500 && e.status !== 429) throw e;
          s.status = "done"; c.attempts += 1;
          if (e.declineCode || e.code) {
            c.lastDecline = e.declineCode || e.code;
            const next = replan(c, { declineCode: c.lastDecline, now, policy });
            c.class = next.class; c.steps = next.steps;
          }
          note(`retry declined: ${c.lastDecline || e.message}`);
        }
      } else if (s.kind === "expire") {
        if (c.arm === "holdout") { s.status = "done"; closeCase(state, c, "lost", now); note("holdout: grace period over, left alone by design"); continue; }
        if (deps.cancelOnExpire && c.subscription && !deps.dryRun) await deps.stripe.cancelSubscription(c.subscription, `dd-${c.invoiceId}-cancel`);
        s.status = "done"; closeCase(state, c, "lost", now);
        note(deps.cancelOnExpire && !deps.dryRun ? "grace period over: subscription cancelled" : "grace period over: left for you to decide");
        await deps.alert?.(`dunning-engine: ${c.invoiceId} (${formatMoney(c.amountMinor, c.currency)}, ${c.email || c.customer}) was not recovered in ${policy.graceDays} days.`);
      }
    } catch (e) {
      s.tries = (s.tries || 0) + 1;
      note(`error: ${e.message}`);
      if (s.tries >= MAX_ATTEMPTS) { s.status = "failed"; await deps.alert?.(`dunning-engine: step ${s.id} on ${c.invoiceId} failed ${MAX_ATTEMPTS} times: ${e.message}`).catch(() => {}); }
      else s.at = now + 5 * 60000 * s.tries; // back off, try again on a later tick
    }
  }
  return done;
}

const SCAN_EVERY_MS = 24 * 3600000;

// Once a day: email customers whose card expires soon, once per card. Skips
// customers who already have an open recovery case (they are being dunned).
// deps adds: expiryNotices (bool), expiryDays, stripe.listSubscriptionsWithCards.
export async function scanExpiring(state, now, deps) {
  if (!deps.expiryNotices) return [];
  const ex = (state.expiry ||= { lastScan: 0, notified: {} });
  if (now - ex.lastScan < SCAN_EVERY_MS) return [];
  const done = [];
  const subs = await deps.stripe.listSubscriptionsWithCards();
  ex.lastScan = now;
  const dunned = new Set(Object.values(state.cases).filter((c) => c.status === "open").map((c) => c.customer));
  for (const x of findExpiring(subs, now, { withinDays: deps.expiryDays ?? 30 })) {
    if (ex.notified[x.pm] || dunned.has(x.customer)) continue;
    if (!x.email) { done.push(`expiry ${x.pm}: no customer email`); continue; }
    const phrase = x.expired ? `expired on ${x.expires}` : `expires ${x.expires}`;
    const mail = renderEmail("expiring", {
      name: x.name || "there", brand: x.brand, last4: x.last4, expiry_phrase: phrase, company: deps.company || "our team",
      address: deps.address || "", update_url: deps.updateUrl({ customer: x.customer }),
    });
    if (deps.dryRun) { done.push(`expiry ${x.pm}: dry run: would email ${x.email} (card ${phrase})`); continue; }
    try { await deps.sendEmail({ to: x.email, ...mail }); } catch (e) { done.push(`expiry ${x.pm}: error: ${e.message}`); continue; }
    ex.notified[x.pm] = now; state.stats.expiryEmails = (state.stats.expiryEmails || 0) + 1;
    done.push(`expiry ${x.pm}: emailed (card ${phrase})`);
  }
  return done;
}

export function summary(state) {
  const open = Object.values(state.cases).filter((c) => c.status === "open");
  const atRisk = {};
  for (const c of open) atRisk[c.currency] = (atRisk[c.currency] || 0) + c.amountMinor;
  const ex = experiment(state.cases);
  return { open: open.length, atRiskMinor: atRisk, ...state.stats, ...(ex ? { experiment: ex } : {}) };
}
export { classifyDecline };

expiry.mjs.text:
// Pre-dunning: find active subscriptions whose card on file expires soon and
// ask the customer to update it before the renewal fails. Pure functions; the
// engine does the sending (see scanExpiring in engine.mjs). Zero dependencies.

// A card is valid through the last day of its expiry month (UTC).
export function cardValidUntil(expMonth, expYear) {
  return Date.UTC(expYear, expMonth, 1) - 1;
}

export function formatExpiry(expMonth, expYear) {
  return `${String(expMonth).padStart(2, "0")}/${expYear}`;
}

const asObj = (x) => (x && typeof x === "object" ? x : null);

// subscriptions: Stripe subscription objects with `default_payment_method` and
// `customer` expanded (customer.invoice_settings.default_payment_method too, as
// the fallback). Returns one entry per card that expires within `withinDays`
// (or has already expired) and belongs to an active or trialing subscription.
export function findExpiring(subscriptions, now, { withinDays = 30 } = {}) {
  const horizon = now + withinDays * 86400000;
  const out = [];
  const seen = new Set();
  for (const sub of subscriptions || []) {
    if (!["active", "trialing", "past_due"].includes(sub.status)) continue;
    if (sub.cancel_at_period_end) continue; // leaving anyway: do not nag
    const customer = asObj(sub.customer);
    const pm = asObj(sub.default_payment_method) || asObj(customer?.invoice_settings?.default_payment_method);
    const card = pm?.card;
    if (!pm?.id || !card?.exp_month || !card?.exp_year) continue;
    if (seen.has(pm.id)) continue; // one card on two subscriptions: one email
    const validUntil = cardValidUntil(card.exp_month, card.exp_year);
    if (validUntil > horizon) continue;
    const email = customer?.email || pm.billing_details?.email || null;
    seen.add(pm.id);
    out.push({
      pm: pm.id, customer: customer?.id || (typeof sub.customer === "string" ? sub.customer : null), subscription: sub.id,
      email, name: customer?.name || pm.billing_details?.name || null,
      last4: card.last4 || "", brand: card.brand || "card", expires: formatExpiry(card.exp_month, card.exp_year),
      validUntil, expired: validUntil < now,
    });
  }
  return out.sort((a, b) => a.validUntil - b.validUntil);
}

holdout.mjs.text:
// Holdout experiment: leave a small, stable share of customers alone and compare
// how many of their failed invoices get paid with how many of the ones we work.
// Pure functions, no network. Arm choice is a hash of the customer id, so every
// invoice of one customer lands in the same arm and a restart changes nothing.
import { createHash } from "node:crypto";

export const MAX_HOLDOUT_PCT = 50;

export function clampPct(v) {
  const n = Number(v);
  return Number.isFinite(n) ? Math.min(MAX_HOLDOUT_PCT, Math.max(0, Math.floor(n))) : 0;
}

export function assignArm(customer, holdoutPct, salt = "dunning-engine") {
  const pct = clampPct(holdoutPct);
  if (!pct) return "treatment";
  const h = createHash("sha256").update(`${salt}:${customer}`).digest();
  return h.readUInt32BE(0) % 100 < pct ? "holdout" : "treatment";
}

const Z = 1.96;

// Wilson score interval for k successes in n trials.
export function wilson(k, n) {
  if (!n) return { p: null, low: null, high: null };
  const p = k / n, z2 = Z * Z;
  const d = 1 + z2 / n;
  const c = (p + z2 / (2 * n)) / d;
  const h = (Z * Math.sqrt((p * (1 - p)) / n + z2 / (4 * n * n))) / d;
  return { p, low: Math.max(0, c - h), high: Math.min(1, c + h) };
}

// Newcombe's hybrid-score interval for the difference of two proportions
// (treatment minus holdout). Behaves at small n and at 0 or 100 percent.
export function diffInterval(k1, n1, k2, n2) {
  const a = wilson(k1, n1), b = wilson(k2, n2);
  if (a.p === null || b.p === null) return null;
  const d = a.p - b.p;
  return {
    diff: d,
    low: d - Math.sqrt((a.p - a.low) ** 2 + (b.high - b.p) ** 2),
    high: d + Math.sqrt((a.high - a.p) ** 2 + (b.p - b.low) ** 2),
  };
}

// Resolved = recovered or lost. Voided and still-open invoices say nothing about
// whether recovery worked, so they stay out of the rates.
function tally(cases) {
  const t = { opened: 0, open: 0, recovered: 0, lost: 0, voided: 0 };
  for (const c of cases) {
    t.opened += 1;
    if (c.status === "open") t.open += 1;
    else if (c.status in t) t[c.status] += 1;
  }
  t.resolved = t.recovered + t.lost;
  t.rate = t.resolved ? t.recovered / t.resolved : null;
  return t;
}

// Rough invoices per arm needed to see `diff` at 80% power, 5% alpha (two-proportion normal approx).
export function casesPerArm(p1, p2) {
  const d = Math.abs(p1 - p2);
  if (!d) return null;
  const pbar = (p1 + p2) / 2;
  const n = ((1.96 * Math.sqrt(2 * pbar * (1 - pbar)) + 0.84 * Math.sqrt(p1 * (1 - p1) + p2 * (1 - p2))) ** 2) / (d * d);
  return Math.ceil(n);
}

export function experiment(cases) {
  const list = Object.values(cases || {}).filter((c) => c.arm);
  const hold = list.filter((c) => c.arm === "holdout");
  if (!hold.length) return null;
  const treatment = tally(list.filter((c) => c.arm === "treatment"));
  const holdout = tally(hold);
  const ci = diffInterval(treatment.recovered, treatment.resolved, holdout.recovered, holdout.resolved);
  let verdict = "Not enough resolved invoices in both groups yet.";
  let needed = null;
  if (ci) {
    if (ci.low > 0) verdict = "Recovery is working: treated invoices are paid more often than the holdout, beyond chance.";
    else if (ci.high < 0) verdict = "Treated invoices are paid less often than the holdout, beyond chance. Check your schedule and wording.";
    else {
      verdict = "No clear difference yet: the interval spans zero. Keep it running; do not read the gap as a win or a loss.";
      needed = casesPerArm(treatment.rate, holdout.rate);
    }
  }
  return { treatment, holdout, difference: ci, casesPerArmNeeded: needed, verdict };
}

server.mjs.text:
#!/usr/bin/env node
// Self-hosted failed-payment recovery for Stripe subscriptions. Zero dependencies.
//   STRIPE_SECRET_KEY=rk_... STRIPE_WEBHOOK_SECRET=whsec_... ADMIN_KEY=... \
//   LINK_SECRET=... PUBLIC_URL=https://dunning.example.com RESEND_API_KEY=... \
//   MAIL_FROM="Billing <billing@example.com>" COMPANY_NAME=Acme node server.mjs
// DRY_RUN defaults to true: it records and logs what it would do and touches
// neither Stripe nor your customers until you set DRY_RUN=false.
import http from "node:http";
import fs from "node:fs";
import { createHmac, timingSafeEqual } from "node:crypto";
import { verifySignature, createStripe } from "./stripe.mjs";
import { ADMIN_HTML, ADMIN_CSP } from "./admin.mjs";
import { clampPct } from "./holdout.mjs";
import { applyEvent, tick, scanExpiring, summary, newState } from "./engine.mjs";

const env = process.env;

export function linkToken(secret, customer) {
  const body = Buffer.from(customer).toString("base64url");
  return `${body}.${createHmac("sha256", secret).update(body).digest("base64url")}`;
}
export function customerFromToken(secret, token) {
  const [body, sig] = String(token).split(".");
  if (!body || !sig) return null;
  const want = createHmac("sha256", secret).update(body).digest();
  const got = Buffer.from(sig, "base64url");
  if (got.length !== want.length || !timingSafeEqual(got, want)) return null;
  return Buffer.from(body, "base64url").toString();
}

const readBody = (req, max = 1_000_000) => new Promise((resolve, reject) => {
  let size = 0; const chunks = [];
  req.on("data", (c) => { size += c.length; if (size > max) { reject(Object.assign(new Error("too large"), { status: 413 })); req.destroy(); } else chunks.push(c); });
  req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
  req.on("error", reject);
});

const bearerOk = (req, key) => {
  const a = Buffer.from(req.headers.authorization || "");
  const b = Buffer.from(`Bearer ${key}`);
  return Boolean(key) && a.length === b.length && timingSafeEqual(a, b);
};

// cfg: {state, save, stripe, webhookSecret, linkSecret, adminKey, publicUrl, policy, dryRun, now}
export function handler(cfg) {
  const now = cfg.now || Date.now;
  return async (req, res) => {
    const url = new URL(req.url, "http://x");
    const send = (code, body, type = "text/plain") => { res.writeHead(code, { "content-type": type }); res.end(typeof body === "string" ? body : JSON.stringify(body, null, 2)); };
    try {
      if (url.pathname === "/healthz") return send(200, "ok\n");
      if (req.method === "POST" && url.pathname === "/webhook/stripe") {
        const raw = await readBody(req);
        if (!verifySignature(raw, req.headers["stripe-signature"], cfg.webhookSecret, Math.floor(now() / 1000))) return send(400, "bad signature\n");
        const event = JSON.parse(raw);
        let declineCode = null;
        if (event.type === "invoice.payment_failed") declineCode = await cfg.stripe.declineCodeFor(event.data.object).catch(() => null);
        const result = applyEvent(cfg.state, event, { now: now(), policy: cfg.policy, declineCode, holdoutPct: cfg.holdoutPct });
        cfg.save();
        return send(200, result, "application/json");
      }
      if (req.method === "GET" && url.pathname.startsWith("/update/")) {
        const customer = customerFromToken(cfg.linkSecret, decodeURIComponent(url.pathname.slice(8)));
        if (!customer) return send(404, "link not valid\n");
        const to = await cfg.stripe.portalUrl(customer, cfg.publicUrl || "https://stripe.com");
        res.writeHead(302, { location: to }); return res.end();
      }
      if (req.method === "GET" && url.pathname === "/admin") {
        res.writeHead(200, { "content-type": "text/html; charset=utf-8", "content-security-policy": ADMIN_CSP, "cache-control": "no-store", "x-content-type-options": "nosniff" });
        return res.end(ADMIN_HTML);
      }
      if (url.pathname === "/v1/summary" || url.pathname === "/v1/cases") {
        if (!bearerOk(req, cfg.adminKey)) return send(401, "admin key required\n");
        if (url.pathname === "/v1/summary") return send(200, { dryRun: cfg.dryRun, ...summary(cfg.state) }, "application/json");
        return send(200, Object.values(cfg.state.cases).map(({ steps, log, ...c }) => ({ ...c, steps: steps.map((s) => ({ id: s.id, kind: s.kind, at: new Date(s.at).toISOString(), status: s.status })), log: log.slice(-5) })), "application/json");
      }
      return send(404, "not found\n");
    } catch (e) {
      console.error("request failed:", e.message);
      return send(e.status || 500, "error\n");
    }
  };
}

function readJson(path, fallback) {
  try { return JSON.parse(fs.readFileSync(path, "utf8")); } catch (e) { if (e.code === "ENOENT") return fallback; throw e; }
}

async function sendResend(msg) {
  const res = await fetch("https://api.resend.com/emails", {
    method: "POST", headers: { authorization: `Bearer ${env.RESEND_API_KEY}`, "content-type": "application/json" },
    body: JSON.stringify({ from: env.MAIL_FROM, to: [msg.to], subject: msg.subject, text: msg.text }),
  });
  if (!res.ok) throw new Error(`resend ${res.status}`);
}

async function alert(text) {
  console.log(text);
  if (env.ALERT_WEBHOOK_URL) await fetch(env.ALERT_WEBHOOK_URL, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ text, content: text }) }).catch(() => {});
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const missing = ["STRIPE_SECRET_KEY", "STRIPE_WEBHOOK_SECRET", "ADMIN_KEY", "LINK_SECRET"].filter((k) => !env[k]);
  if (missing.length) { console.error(`missing env: ${missing.join(", ")}`); process.exit(1); }
  const dryRun = env.DRY_RUN !== "false";
  const statePath = env.STATE || "state.json";
  const state = readJson(statePath, newState());
  const save = () => { fs.writeFileSync(`${statePath}.tmp`, JSON.stringify(state)); fs.renameSync(`${statePath}.tmp`, statePath); };
  const stripe = createStripe({ key: env.STRIPE_SECRET_KEY });
  const policy = env.POLICY_JSON ? JSON.parse(env.POLICY_JSON) : {};
  const publicUrl = (env.PUBLIC_URL || "").replace(/\/$/, "");
  const deps = {
    stripe, policy, dryRun, alert, sendEmail: sendResend, company: env.COMPANY_NAME, address: env.COMPANY_ADDRESS,
    cancelOnExpire: env.CANCEL_ON_EXPIRE === "true",
    expiryNotices: env.EXPIRY_NOTICES !== "false", expiryDays: Number(env.EXPIRY_DAYS || 30),
    updateUrl: (c) => (publicUrl ? `${publicUrl}/update/${linkToken(env.LINK_SECRET, c.customer)}` : c.hostedUrl || ""),
  };
  if (!dryRun && (!env.RESEND_API_KEY || !env.MAIL_FROM)) { console.error("DRY_RUN=false needs RESEND_API_KEY and MAIL_FROM"); process.exit(1); }
  setInterval(async () => { try { const now = Date.now();
    const log = [...await tick(state, now, deps), ...await scanExpiring(state, now, deps).catch((e) => [`expiry scan failed: ${e.message}`])]; log.forEach((l) => console.log(l)); if (log.length) save(); } catch (e) { console.error("tick failed:", e.message); } }, 60000).unref?.();
  const cfg = { state, save, stripe, webhookSecret: env.STRIPE_WEBHOOK_SECRET, linkSecret: env.LINK_SECRET, adminKey: env.ADMIN_KEY, publicUrl, policy, dryRun, holdoutPct: clampPct(env.HOLDOUT_PCT) };
  http.createServer(handler(cfg)).listen(Number(env.PORT || 8080), () => console.log(`dunning-engine on :${env.PORT || 8080} (${dryRun ? "DRY RUN" : "LIVE"})`));
}

stripe.mjs.text:
// Minimal Stripe pieces, no SDK: webhook signature verification and the four
// API calls recovery needs. Use a restricted key (rk_...) with Invoices: write,
// Customer portal: write, Subscriptions: write (only if you enable cancelling),
// PaymentIntents: read, Customers: read, Subscriptions: read (expiry notices),
// PaymentMethods: read.
import { createHmac, timingSafeEqual } from "node:crypto";

export function verifySignature(rawBody, header, secret, nowSec = Math.floor(Date.now() / 1000), toleranceSec = 300) {
  if (!header || !secret) return false;
  const parts = String(header).split(",").map((p) => p.trim().split("="));
  const t = parts.find(([k]) => k === "t")?.[1];
  const sigs = parts.filter(([k]) => k === "v1").map(([, v]) => v);
  if (!t || !sigs.length || !/^\d+$/.test(t)) return false;
  if (Math.abs(nowSec - Number(t)) > toleranceSec) return false;
  const want = createHmac("sha256", secret).update(`${t}.${rawBody}`).digest();
  return sigs.some((s) => {
    const got = Buffer.from(s, "hex");
    return got.length === want.length && timingSafeEqual(got, want);
  });
}

export function signPayload(rawBody, secret, tSec) {
  return `t=${tSec},v1=${createHmac("sha256", secret).update(`${tSec}.${rawBody}`).digest("hex")}`;
}

const form = (obj) => new URLSearchParams(Object.entries(obj).filter(([, v]) => v !== undefined && v !== null)).toString();

export function createStripe({ key, fetchImpl = fetch, base = "https://api.stripe.com" }) {
  async function call(method, path, body, headers = {}) {
    const res = await fetchImpl(`${base}${path}`, {
      method,
      headers: { authorization: `Bearer ${key}`, "content-type": "application/x-www-form-urlencoded", ...headers },
      body: body ? form(body) : undefined,
    });
    const json = await res.json().catch(() => ({}));
    if (!res.ok) {
      const e = new Error(json?.error?.message || `stripe ${res.status}`);
      e.status = res.status; e.code = json?.error?.code; e.declineCode = json?.error?.decline_code; e.body = json;
      throw e;
    }
    return json;
  }
  return {
    getInvoice: (id) => call("GET", `/v1/invoices/${encodeURIComponent(id)}`),
    // Pay an open invoice with the customer's default payment method. A decline
    // comes back as a 402 error carrying decline_code, which the caller records.
    payInvoice: (id, idempotencyKey) => call("POST", `/v1/invoices/${encodeURIComponent(id)}/pay`, {}, { "idempotency-key": idempotencyKey }),
    // The decline code lives on the PaymentIntent. Older API versions put the
    // intent on the invoice; 2025+ versions list it under invoice_payments.
    async declineCodeFor(invoice) {
      let pi = invoice.payment_intent;
      if (!pi) {
        const list = await call("GET", `/v1/invoice_payments?invoice=${encodeURIComponent(invoice.id)}&limit=1`).catch(() => null);
        pi = list?.data?.[0]?.payment?.payment_intent;
      }
      const id = typeof pi === "string" ? pi : pi?.id;
      if (!id) return null;
      const intent = typeof pi === "object" && pi.last_payment_error ? pi : await call("GET", `/v1/payment_intents/${encodeURIComponent(id)}`);
      const err = intent.last_payment_error;
      return err?.decline_code || err?.code || null;
    },
    // Portal session URLs are short-lived, so emails link to this service's own
    // /update/<token> route, which mints a fresh session on click.
    portalUrl: async (customer, returnUrl) => (await call("POST", "/v1/billing_portal/sessions", { customer, return_url: returnUrl })).url,
    // Active subscriptions with the card (and customer) expanded, for expiry
    // notices. Pages of 100, capped so a huge account cannot run away.
    async listSubscriptionsWithCards(maxPages = 50) {
      const out = [];
      let after;
      for (let i = 0; i < maxPages; i++) {
        const q = new URLSearchParams({ status: "active", limit: "100" });
        for (const e of ["data.default_payment_method", "data.customer", "data.customer.invoice_settings.default_payment_method"]) q.append("expand[]", e);
        if (after) q.set("starting_after", after);
        const page = await call("GET", `/v1/subscriptions?${q}`);
        out.push(...page.data);
        if (!page.has_more || !page.data.length) break;
        after = page.data[page.data.length - 1].id;
      }
      return out;
    },
    cancelSubscription: (id, idempotencyKey) => call("DELETE", `/v1/subscriptions/${encodeURIComponent(id)}`, null, { "idempotency-key": idempotencyKey }),
  };
}

templates.mjs.text:
// Plain-text dunning emails. Neutral on purpose: no mention of "stolen",
// "fraud" or other issuer reasons, because the customer may be the victim and
// the decline reason is the bank's, not ours. {{placeholders}} are filled by
// renderEmail; unknown placeholders are left visible so a typo is noticed.

const FOOT = "\n\n{{company}}\n{{address}}";

const BODY = {
  first: {
    subject: "Your payment for {{company}} didn't go through",
    text: "Hi {{name}},\n\nWe couldn't collect {{amount}} for your {{company}} subscription.\n\nUpdate your payment method here and we'll try again right away:\n{{update_url}}\n\nIf you've already sorted this out, you can ignore this email.",
  },
  reminder: {
    subject: "Reminder: please update your payment method",
    text: "Hi {{name}},\n\nYour {{amount}} payment for {{company}} is still unpaid. To keep your access without interruption, please update your payment method:\n{{update_url}}",
  },
  final: {
    subject: "Final notice: {{company}} access ends {{deadline}}",
    text: "Hi {{name}},\n\nThis is the last reminder about your unpaid {{amount}}. Unless the payment is updated by {{deadline}}, your subscription will be ended.\n\nUpdate your payment method:\n{{update_url}}",
  },
};

const AUTH = {
  first: {
    subject: "Your bank needs you to confirm a payment to {{company}}",
    text: "Hi {{name}},\n\nYour bank asked you to confirm the {{amount}} payment for {{company}}. We can't do this for you; it takes a minute on your side:\n{{update_url}}",
  },
};

const EXPIRING = {
  subject: "Your card ending {{last4}} {{expiry_phrase}}",
  text: "Hi {{name}},\n\nThe {{brand}} card ending {{last4}} that pays for your {{company}} subscription {{expiry_phrase}}. To avoid a failed payment at your next renewal, please add a new card:\n{{update_url}}\n\nIf you've already done this, you can ignore this email.",
};

export function templateFor(name) {
  if (name === "expiring") return EXPIRING;
  const [cls, stage] = name.split("-");
  if (cls === "auth") return stage === "first" ? AUTH.first : { ...BODY[stage], text: BODY[stage].text.replace("update your payment method", "confirm the payment with your bank") };
  return BODY[stage] || BODY.reminder;
}

export function renderEmail(name, vars) {
  const t = templateFor(name);
  const fill = (s) => s.replace(/\{\{(\w+)\}\}/g, (m, k) => (vars[k] === undefined || vars[k] === null || vars[k] === "" ? m : String(vars[k])));
  return { subject: fill(t.subject), text: fill(t.text + FOOT) };
}

usage.mjs.text:
const KEY = "dunning-engine-usage";
// Separate from the counters on purpose: opting out *removes* the
// counters, so a flag stored inside them would be deleted by the very
// act it records.
const OPT_OUT = "dunning-engine-usage-opt-out";

// The in-memory flag is only a same-page fast path. `globalThis` is a
// fresh realm on every page load, so without the stored key the switch
// silently stops working on the visitor's next visit -- and they do not
// look again, because they believe they already used it.
function usageOptedOut() {
  if (globalThis.__usageOptOut) return true;
  try {
    return typeof localStorage !== "undefined" && localStorage.getItem(OPT_OUT) === "1";
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

function usageBlocked() {
  if (usageOptedOut()) return true;
  try {
    if (navigator.doNotTrack === "1" || navigator.globalPrivacyControl) return true;
  } catch {
    /* navigator is optional in tests */
  }
  return false;
}

export function record(event) {
  if (typeof localStorage === "undefined" || usageBlocked()) return;
  let current;
  try {
    current = JSON.parse(localStorage.getItem(KEY) || "{}");
  } catch {
    current = {};
  }
  if (!current || typeof current !== "object" || Array.isArray(current)) current = {};
  current[event] = (current[event] || 0) + 1;
  try {
    localStorage.setItem(KEY, JSON.stringify(current));
  } catch {
    /* storage is optional */
  }
}

export function readUsage() {
  if (typeof localStorage === "undefined") return {};
  try {
    const parsed = JSON.parse(localStorage.getItem(KEY) || "{}");
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

export function setUsageOptOut(value) {
  const off = Boolean(value);
  globalThis.__usageOptOut = off;
  if (typeof localStorage === "undefined") return;
  if (off) {
    try { localStorage.removeItem(KEY); } catch { /* storage is optional */ }
    try { localStorage.setItem(OPT_OUT, "1"); } catch { /* storage is optional */ }
  } else {
    try { localStorage.removeItem(OPT_OUT); } catch { /* storage is optional */ }
  }
}

export { usageOptedOut };
